interface Operation { visitCircle(c: Circle): void; visitSquare(s: Square): void }
abstract class Shape { abstract accept(op: Operation): void }
class Circle extends Shape { accept(op: Operation) { op.visitCircle(this); } }
class Square extends Shape { accept(op: Operation) { op.visitSquare(this); } }
class Render implements Operation { visitCircle(c: Circle) { /*...*/ } visitSquare(s: Square) { /*...*/ } }

interface Operation { visitOrder(o: Order): void; visitCustomer(c: Customer): void }
abstract class Entity { abstract accept(op: Operation): void }
class Order extends Entity { accept(op: Operation) { op.visitOrder(this); } }
class Customer extends Entity { accept(op: Operation) { op.visitCustomer(this); } }
class ExportCsv implements Operation { visitOrder(o: Order) { /*...*/ } visitCustomer(c: Customer) { /*...*/ } }

